def policy(board: list[list[int]]) -> tuple[int, int]:
    # Helper function to check if a line has 3 of one player and 1 empty
    def check_line_for_win(line):
        count_me = sum(1 for cell in line if cell == 1)
        count_empty = sum(1 for cell in line if cell == 0)
        if count_me == 3 and count_empty == 1:
            # Found my winning move
            for i, cell in enumerate(line):
                if cell == 0:
                    return i
        return None

    def check_line_for_block(line):
        count_opponent = sum(1 for cell in line if cell == -1)
        count_empty = sum(1 for cell in line if cell == 0)
        if count_opponent == 3 and count_empty == 1:
            for i, cell in enumerate(line):
                if cell == 0:
                    return i
        return None

    # Check all rows
    for row in range(4):
        line = [board[row][col] for col in range(4)]
        result = check_line_for_win(line)
        if result is not None:
            return (row, result)

    # Check all columns
    for col in range(4):
        line = [board[row][col] for row in range(4)]
        result = check_line_for_win(line)
        if result is not None:
            return (result, col)

    # Check main diagonal
    line = [board[i][i] for i in range(4)]
    result = check_line_for_win(line)
    if result is not None:
        return (result, result)

    # Check anti-diagonal
    line = [board[i][3-i] for i in range(4)]
    result = check_line_for_win(line)
    if result is not None:
        return (result, 3-result)

    # Block opponent wins
    for row in range(4):
        line = [board[row][col] for col in range(4)]
        result = check_line_for_block(line)
        if result is not None:
            return (row, result)

    for col in range(4):
        line = [board[row][col] for row in range(4)]
        result = check_line_for_block(line)
        if result is not None:
            return (result, col)

    line = [board[i][i] for i in range(4)]
    result = check_line_for_block(line)
    if result is not None:
        return (result, result)

    line = [board[i][3-i] for i in range(4)]
    result = check_line_for_block(line)
    if result is not None:
        return (result, 3-result)

    # Strategic moves: center, then corners, then others
    center = [(1,1), (1,2), (2,1), (2,2)]
    for r, c in center:
        if board[r][c] == 0:
            return (r, c)

    corners = [(0,0), (0,3), (3,0), (3,3)]
    for r, c in corners:
        if board[r][c] == 0:
            return (r, c)

    # Any other empty cell
    for r in range(4):
        for c in range(4):
            if board[r][c] == 0:
                return (r, c)

    # Should never reach here if board has empty cells
    return (0, 0)
